import { StatusBar } from 'expo-status-bar';
import { NavigationContainer } from '@react-navigation/native';
import { createNativeStackScreenOptions, createNativeStackNavigator } from '@react-navigation/native-stack';
import type { RootStackParamList } from './navigation/types';
import HomeScreen from './screens/HomeScreen';
import HealthScreen from './screens/HealthScreen';
import TranscribeScreen from './screens/TranscribeScreen';

const Stack = createNativeStackNavigator<RootStackParamList>();

export default function App() {
  return (
    <NavigationContainer>
      <StatusBar style="auto" />
      <Stack.Navigator initialRouteName="Home">
        <Stack.Screen
          name="Home"
          component={HomeScreen}
          options={{ title: 'Native Bench' }}
        />
        <Stack.Screen
          name="Health"
          component={HealthScreen}
          options={{ title: 'Health' }}
        />
        <Stack.Screen
          name="Transcribe"
          component={TranscribeScreen}
          options={{ title: 'Transcribe' }}
        />
      </Stack.Navigator>
    </NavigationContainer>
  );
}

